const input = Array.isArray($json) ? $json : [$json];
const rows = input.map((call) => {
  const text = `${call.voicemailText ?? ''}`.toLowerCase();
  const callTime = `${call.callTime ?? ''}`;
  const afterHours = /T(17|18|19|20|21|22|23):/.test(callTime);
  const datePart = callTime.slice(0, 10);
  const day = datePart.length === 10 ? new Date(`${datePart}T12:00:00Z`).getUTCDay() : null;
  const weekend = day === 0 || day === 6;
  const safetyFlag = ['gas smell', 'smell gas', 'gas leak', 'sewage', 'flooding'].some((term) => text.includes(term));
  const emergency = ['burst pipe', 'pipe burst', 'no water', 'water heater', 'water everywhere'].some((term) => text.includes(term));
  const priorityScore = (safetyFlag ? 5 : 0) + (emergency ? 3 : 0) + (afterHours ? 1 : 0) + (weekend ? 1 : 0) + (call.repeatCaller ? 1 : 0);
  const queue = safetyFlag ? 'human-now' : priorityScore >= 3 ? 'call-now' : 'next-business-block';
  return { ...call, afterHours, weekend, safetyFlag, priorityScore, queue };
});
return rows.sort((a, b) => b.priorityScore - a.priorityScore).map((row) => ({ json: row }));
